# -*- coding: utf-8 -*-
"""
uborka_ostrova.py — уборщик на Острове и свой адрес (27.09).

  • кладёт uborshchik.py — уборщик острова, тот же, что в городе, со
    списками острова. Сверх городского: «засело в репе» — кэш питона и
    старые переезды, которые .gitignore уже закрыл, но они попали в
    репу раньше; их он убирает ИЗ РЕПЫ, на диске они остаются;
  • руки острова: на плашке вторым рядом рука УБОРКА (рядом с ПРОПИСКОЙ);
  • остров переезжает на свой адрес: http://localhost:8081. Город
    остаётся на 8080 — теперь их можно держать открытыми вместе, и
    пульс острова домой по-прежнему идёт на 8080.

Класть в КОРЕНЬ ОСТРОВА, запускать двойным кликом. Потом перезапустить
остров (ОСТРОВ.bat — браузер сам откроет новый адрес). Повтор ничего
не дублирует.
"""
import ast
import shutil
import sys
from pathlib import Path

if sys.platform == "win32":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass

OSTROV = Path(__file__).resolve().parent
METKA_UB = "UBORSHCHIK_OSTROVA_V1"
METKA_RUKI = "RUKI_OSTROVA_V3"
METKA_PORT = "OSTROV_PORT_8081_V1"

UBORSHCHIK = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n# UBORSHCHIK_V1\n# UBORSHCHIK_OSTROVA_V1\n"""\nУБОРЩИК ОСТРОВА — тот же, что в городе, со списками острова (27.09).\nЗовётся рукой УБОРКА на плашке главной; можно и из терминала.\n\nСверх городского умеет одно: «ЗАСЕЛО В РЕПЕ» — файлы, которые .gitignore\nуже велит не класть в репо (кэш питона, старые переезды), но они попали\nтуда раньше правила. Их он убирает ИЗ РЕПЫ (git rm --cached), а на диске\nони остаются как были. Фон острова не трогает.\n\nУБОРЩИК — отделяет работающее от отработавшего. Ничего не удаляет.\n\n    python uborshchik.py --suho     посмотреть, что нашёл (по умолчанию)\n    python uborshchik.py --ubrat    перенести найденное в чулан\n\n    python uborshchik.py --ubrat --kopii        только копии .bak/.snesen\n    python uborshchik.py --ubrat --patchi       только отработавшие патчи\n    python uborshchik.py --ubrat --odnorazovye  только разовые инструменты\n    python uborshchik.py --ubrat --otsluzhivshie только заменённое\n\nЗапускать из КОРНЯ репо.\n\nЗАКОН ЭТОГО СКРИПТА\n\n    Не удаляет. Переносит в `_УБОРКА/{дата}/`, сохраняя дорожки, и\n    кладёт рядом манифест: что, откуда, какого размера и ПОЧЕМУ. Любой\n    файл возвращается на место одной строкой из манифеста.\n\n    По умолчанию — сухой прогон. Убирает только по прямому `--ubrat`.\n\n    Работающее не трогает вообще: движки, кабинеты, мозги, знания,\n    паспорта, документы города, данные. Список неприкасаемых — ниже, и\n    он проверяется до всякого переноса.\n\nКАК ОН РЕШАЕТ, ЧТО ОТРАБОТАЛО\n\n    ПАТЧИ — по маркеру. Каждый патч, накатываясь, оставляет в целевом\n    файле свою метку. Уборщик читает метку из самого патча и ищет её по\n    репо. Нашлась — патч сделал дело, его место в чулане. НЕ нашлась —\n    патч ещё не накатан, и уборщик его НЕ ТРОГАЕТ, а говорит об этом.\n    Правило работает и для будущих патчей, ничего дописывать не надо.\n\n    КОПИИ — по имени: `*.bak*` и `*.snesen`. Это следы патчей, а не\n    работа. Оригиналы на месте, история в git.\n\n    РАЗОВЫЕ ИНСТРУМЕНТЫ и ЗАМЕНЁННОЕ — поимённо, с причиной у каждого.\n    Наугад тут нельзя, поэтому список короткий и проверяемый.\n\nЧТО ОН ПОКАЗЫВАЕТ, НО НЕ ТРОГАЕТ\n\n    «Под вопросом» — файлы, которых никто не зовёт: ни импортом, ни по\n    имени. Это ПОДОЗРЕНИЕ, а не приговор: скрипт могли запускать руками\n    или он ждёт своего часа. Решает Шеф, уборщик только показывает.\n"""\nimport argparse\nimport ast\nimport json\nimport re\nimport shutil\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nif sys.platform == "win32":\n    try:\n        sys.stdout.reconfigure(encoding="utf-8")\n    except Exception:\n        pass\n\nKOREN = Path(__file__).resolve().parent\nCHULAN = KOREN / "_УБОРКА"\nYA = Path(__file__).name\n\n# ── куда не заходим вовсе ─────────────────────────────────────\nNE_ZAHODIT = {"_ARCHIVE", "_OLD", "_АРХИВ_ЧИСТКИ", "_УБОРКА",\n              "_ПЕРЕЕЗД", "_ОТПРАВКА", "_ПРИБЫТИЕ", "фон",\n              ".git", ".vscode", "__pycache__", "node_modules"}\n\n# ── папки, которые грузятся ЦЕЛИКОМ, по имени папки ───────────\n# `истоки/` и `памяти/` — плагины: обходчик берёт папку и подхватывает\n# каждый файл сам. Их никто не импортирует по имени, и это НОРМАЛЬНО:\n# так задумано. Без этой оговорки уборщик записал бы их в мёртвые.\nPLAGINY = ("истоки", "памяти")\n\n# ── что не трогаем ни при каких условиях ──────────────────────\n# Точки входа и живые двери города. Их «никто не импортирует» — это\n# нормально: их запускает Шеф руками, а не код.\nNEPRIKASAEMYE = {\n    # живые двери ОСТРОВА: запуск, главная, её руки, перевозка, Застройщик,\n    # пульс домой, переселение (им остров подтягивает Биржу с материка)\n    "ostrov_main.py", "остров.py", "ostrov_puls.py", "ui_ostrov.py",\n    "ruki_ostrova.py", "uborshchik.py", "perevozka.py", "ui_perevozka.py",\n    "ui_zastroyshchik.py", "pereselenie_2.py", "ubrat_klyuch.py",\n    "sostoyanie.py",\n}\n\n# ── разовые инструменты: сделали дело, лежат мёртвым весом ────\nRAZOVYE = {\n    # ключ «./имя» — только корень острова. Бирж\xadевые файлы здесь не\n    # убираем: они зеркало материка, переселение привезёт их снова.\n    "./pereselenie.py": "первое переселение (10.08, эпоха Искры) — заменено pereselenie_2.py",\n    "./obnovit_doki.py": "разовая правка документов от 13.08 — документы с тех пор переписаны",\n}\n\n# батники: у каждого теперь есть кнопка или страница в городе\nBATNIKI = {}   # ОСТРОВ.bat и УБРАТЬ_КЛЮЧ.bat — живые\n\n# ── заменённое: работу делает кто-то другой ───────────────────\nOTSLUZHIVSHIE = {}\n\n\ndef _vnutri_arhiva(p: Path) -> bool:\n    return any(part in NE_ZAHODIT for part in p.parts)\n\n\ndef _vse_faily():\n    for p in KOREN.rglob("*"):\n        if p.is_file() and not _vnutri_arhiva(p.relative_to(KOREN)):\n            yield p\n\n\ndef _tekstovye():\n    """Файлы, в которых имеет смысл искать маркеры и упоминания."""\n    for p in _vse_faily():\n        if p.suffix.lower() in (".py", ".md", ".json", ".txt"):\n            try:\n                yield p, p.read_text(encoding="utf-8", errors="replace")\n            except Exception:\n                continue\n\n\n# ══════════════════════════════════════════════════════════════\n# СБОР\n# ══════════════════════════════════════════════════════════════\n\ndef sobrat_kopii() -> list:\n    """Следы патчей: *.bak* и *.snesen. Оригиналы на месте."""\n    out = []\n    for p in _vse_faily():\n        n = p.name\n        if ".bak" in n or n.endswith(".snesen"):\n            out.append((p, "копия, оставленная патчем (оригинал на месте)"))\n    return out\n\n\n# METKI_LYUBYE_V1 (27.09): метка патча — не только MARKER. Наши патчи\n# зовут её и METKA, и METKA_SV, и MARKER_G — уборщик видел только\n# первую форму, и десятки накатанных патчей лежали в корне вечно.\n# Теперь берётся любая константа MARKER*/METKA*, из её значения —\n# слово вида ЧТО_ТО_V1. Накатан, только если стоят ВСЕ его метки.\n# Ищем их в городе, но НЕ в соседних патчах корня: метка, которую\n# лишь упомянул другой патч, ещё не значит, что работа сделана.\n_METKA_IMYA = re.compile(r\'^(?:MARKER|METKA)[A-Z0-9_]*\\s*=\\s*[\\\'"]([^\\\'"\\n]+)[\\\'"]\', re.M)\n_METKA_ZNAK = re.compile(r\'[A-Z][A-Z0-9_]*_V\\d+\')\n\n\ndef _metki_patcha(src: str) -> list:\n    out = []\n    for m in _METKA_IMYA.finditer(src):\n        z = _METKA_ZNAK.search(m.group(1))\n        if z and z.group(0) not in out:\n            out.append(z.group(0))\n    return out\n\n\ndef sobrat_patchi(teksty: dict) -> tuple:\n    """Патчи, чьи метки уже стоят в городе, — значит отработали.\n\n    Возвращает (отработавшие, не_тронутые)."""\n    gotovye, zhdut = [], []\n    gde_iskat = {q: t for q, t in teksty.items()\n                 if not (q.parent == KOREN and q.suffix == ".py"\n                         and q.name not in NEPRIKASAEMYE)}\n    for p in sorted(KOREN.glob("*.py")):\n        if p.name in NEPRIKASAEMYE:\n            continue\n        if ("./" + p.name) in RAZOVYE:   # RASKLADKA_27_09_V1: уберётся списком\n            continue\n        try:\n            src = p.read_text(encoding="utf-8", errors="replace")\n        except Exception:\n            continue\n        metki = _metki_patcha(src)\n        if not metki:\n            zhdut.append((p, "меток внутри нет — что это, не знаю; реши сам"))\n            continue\n        net = [m for m in metki\n               if not any(m in t for t in gde_iskat.values())]\n        if net:\n            zhdut.append((p, f"метки {net[0]} в городе нет — патч ещё НЕ накатан"))\n            continue\n        gde = sorted({q.name for q, t in gde_iskat.items() if metki[0] in t})\n        gotovye.append((p, f"накатан — метка {metki[0][:28]} "\n                           f"стоит в {\', \'.join(gde[:3])}"))\n    return gotovye, zhdut\n\n\ndef sobrat_batniki() -> list:\n    """Батники, которым в городе нашлась кнопка. Ищем только в корне."""\n    out = []\n    for imya, prichina in BATNIKI.items():\n        p = KOREN / imya\n        if p.exists():\n            out.append((p, prichina))\n    return out\n\n\ndef _po_puti(klyuch: str) -> Path:\n    """RASKLADKA_27_09_V1: «./имя» — корень, «Дом/имя» — точно там."""\n    return KOREN / (klyuch[2:] if klyuch.startswith("./") else klyuch)\n\n\ndef sobrat_poimenno(spisok: dict) -> list:\n    out = []\n    # ключ с «/» — точный путь от корня (одноимённые в домах не трогаем)\n    for k, prichina in spisok.items():\n        if "/" in k:\n            p = _po_puti(k)\n            if p.is_file() and not _vnutri_arhiva(p.relative_to(KOREN)):\n                out.append((p, prichina))\n    for p in _vse_faily():\n        if p.name in spisok and p.name not in NEPRIKASAEMYE:\n            out.append((p, spisok[p.name]))\n    return out\n\n\ndef sobrat_pod_voprosom(teksty: dict) -> list:\n    """Модули, которых никто не зовёт. ПОКАЗЫВАЕМ, не трогаем."""\n    py = [p for p in _vse_faily() if p.suffix == ".py"]\n    importy = set()\n    for p in py:\n        try:\n            tree = ast.parse(teksty.get(p, ""))\n        except Exception:\n            continue\n        for n in ast.walk(tree):\n            if isinstance(n, ast.Import):\n                for a in n.names:\n                    importy.add(a.name.split(".")[0])\n            elif isinstance(n, ast.ImportFrom) and n.module:\n                importy.add(n.module.split(".")[0])\n    vsyo = "\\n".join(teksty.values())\n    out = []\n    for p in py:\n        if p.name in NEPRIKASAEMYE or p.name == YA:\n            continue\n        if p.name.startswith(("patch_", "postavit_")):\n            continue\n        if p.parent == KOREN and _metki_patcha(teksty.get(p, "")):\n            continue          # патч с меткой — его судит сбор патчей\n        if p.name in RAZOVYE or p.name in OTSLUZHIVSHIE:\n            continue\n        if str(p.relative_to(KOREN)).replace("\\\\", "/") in RAZOVYE or \\\n                ("./" + p.name) in RAZOVYE and p.parent == KOREN:\n            continue\n        if p.name == "kalibrovka.py":\n            continue          # показан отдельно, как недоделка\n        if p.stem in importy:\n            continue\n        if any(part in PLAGINY for part in p.relative_to(KOREN).parts):\n            continue          # плагин: грузится по папке, не по имени\n        if vsyo.count(p.name) > 1:      # упоминается где-то по имени\n            continue\n        out.append(p)\n    return out\n\n\n# ══════════════════════════════════════════════════════════════\n# ЗАСЕЛО В РЕПЕ — .gitignore велит не класть, а оно уже там\n# ══════════════════════════════════════════════════════════════\n\nNE_TROGAT_V_REPE = ("фон/",)   # картинка острова — пусть едет с репой\n\n\ndef _git(*args):\n    import subprocess\n    return subprocess.run(["git", "-c", "core.quotepath=false", *args],\n                          cwd=str(KOREN), capture_output=True, text=True,\n                          encoding="utf-8", errors="replace")\n\n\ndef zaselo_v_repe() -> list:\n    """Файлы, которые git хранит, хотя .gitignore их уже закрыл."""\n    try:\n        r = _git("ls-files", "-ci", "--exclude-standard")\n    except Exception:\n        return []\n    if r.returncode != 0:\n        return []\n    out = []\n    for stroka in r.stdout.splitlines():\n        s = stroka.strip().strip(\'"\')\n        if s and not s.startswith(NE_TROGAT_V_REPE):\n            out.append(s)\n    return out\n\n\ndef ubrat_iz_repy(puti: list) -> tuple:\n    """git rm --cached: из репы уходит, на диске остаётся."""\n    if not puti:\n        return True, "нечего"\n    ubrano = 0\n    for i in range(0, len(puti), 100):\n        kusok = puti[i:i + 100]\n        r = _git("rm", "-r", "--cached", "--quiet", "--", *kusok)\n        if r.returncode != 0:\n            return False, (r.stderr or r.stdout or "git не справился").strip()[:300]\n        ubrano += len(kusok)\n    return True, (f"из репы убрано {ubrano} — на диске всё на месте. "\n                  "Отправь изменения в GitHub, как обычно.")\n\n\n# ══════════════════════════════════════════════════════════════\n# ПЕРЕНОС\n# ══════════════════════════════════════════════════════════════\n\ndef perenesti(nahodki: list, ubrat: bool) -> dict:\n    if not nahodki:\n        return {}\n    kuda = CHULAN / datetime.now().strftime("%Y%m%d_%H%M%S")\n    manifest = []\n    _bylo = set()   # RASKLADKA_27_09_V1: один файл — один переезд\n    for p, prichina in nahodki:\n        if p in _bylo or not p.exists():\n            continue\n        _bylo.add(p)\n        otn = p.relative_to(KOREN)\n        zapis = {"откуда": str(otn), "размер": p.stat().st_size,\n                 "почему": prichina}\n        if ubrat:\n            cel = kuda / otn\n            cel.parent.mkdir(parents=True, exist_ok=True)\n            shutil.move(str(p), str(cel))\n            zapis["куда"] = str(cel.relative_to(KOREN))\n        manifest.append(zapis)\n    if ubrat:\n        (kuda / "манифест.json").write_text(\n            json.dumps({"когда": datetime.now().isoformat(timespec="seconds"),\n                        "всего": len(manifest), "файлы": manifest},\n                       ensure_ascii=False, indent=2), encoding="utf-8")\n        (kuda / "КАК_ВЕРНУТЬ.txt").write_text(\n            "Ничего не удалено — всё лежит здесь, дорожки сохранены.\\n"\n            "Вернуть один файл: скопировать его отсюда обратно по пути\\n"\n            "из поля «откуда» в манифест.json.\\n"\n            "Вернуть всё: скопировать содержимое этой папки в корень репо\\n"\n            "с сохранением дорожек (манифест и эту записку не копировать).\\n",\n            encoding="utf-8")\n    return {"папка": kuda, "манифест": manifest}\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--ubrat", action="store_true",\n                    help="реально перенести (без него — только показ)")\n    ap.add_argument("--suho", action="store_true", help="только показать")\n    ap.add_argument("--kopii", action="store_true")\n    ap.add_argument("--patchi", action="store_true")\n    ap.add_argument("--odnorazovye", action="store_true")\n    ap.add_argument("--otsluzhivshie", action="store_true")\n    a = ap.parse_args()\n\n    if not (KOREN / "GRONDHEIM_CITY").exists():\n        print("x не вижу GRONDHEIM_CITY — запускай из КОРНЯ репо")\n        return 1\n\n    vybrany = any([a.kopii, a.patchi, a.odnorazovye, a.otsluzhivshie])\n    hochu = {\n        "копии": a.kopii or not vybrany,\n        "патчи": a.patchi or not vybrany,\n        "разовые": a.odnorazovye or not vybrany,\n        "заменённое": a.otsluzhivshie or not vybrany,\n    }\n    ubrat = a.ubrat and not a.suho\n\n    print("=" * 66)\n    print("УБОРЩИК" + ("" if ubrat else "   [СУХОЙ ПРОГОН — ничего не трогаю]"))\n    print("=" * 66)\n\n    teksty = dict(_tekstovye())\n    gotovye, zhdut = sobrat_patchi(teksty)\n\n    gruppy = []\n    if hochu["копии"]:\n        gruppy.append(("КОПИИ, ОСТАВЛЕННЫЕ ПАТЧАМИ", sobrat_kopii()))\n    if hochu["патчи"]:\n        gruppy.append(("ПАТЧИ, КОТОРЫЕ УЖЕ ОТРАБОТАЛИ", gotovye))\n    if hochu["разовые"]:\n        gruppy.append(("РАЗОВЫЕ ИНСТРУМЕНТЫ", sobrat_poimenno(RAZOVYE)))\n    if hochu["заменённое"]:\n        gruppy.append(("ЗАМЕНЁННОЕ ДРУГИМ", sobrat_poimenno(OTSLUZHIVSHIE)))\n        gruppy.append(("БАТНИКИ, У КОТОРЫХ ЕСТЬ КНОПКА", sobrat_batniki()))\n\n    nahodki = []\n    for imya, spisok in gruppy:\n        print(f"\\n── {imya} — {len(spisok)} ──")\n        for p, prichina in sorted(spisok, key=lambda x: str(x[0])):\n            print(f"   {p.relative_to(KOREN)}")\n            print(f"      · {prichina}")\n        nahodki += spisok\n\n    if zhdut:\n        print(f"\\n── ПАТЧИ, КОТОРЫЕ НЕ ТРОГАЮ — {len(zhdut)} ──")\n        for p, prichina in zhdut:\n            print(f"   {p.name}\\n      · {prichina}")\n\n    # не мусор, а НЕДОДЕЛКА: задумка живёт в манифесте цеха, кода никто\n    # не зовёт. Такое не выбрасывают — про такое напоминают.\n    NEDODELKI = {}\n    nedodelano = [p for p in _vse_faily() if p.name in NEDODELKI]\n    if nedodelano:\n        print(f"\\n── НЕ ПОДКЛЮЧЕНО (показываю, НЕ трогаю) — "\n              f"{len(nedodelano)} ──")\n        print("   Это не мусор. Это задумка, до которой руки не дошли.")\n        for p in sorted(nedodelano, key=str):\n            print(f"   {p.relative_to(KOREN)}")\n            print(f"      · {NEDODELKI[p.name]}")\n\n    pod_voprosom = sobrat_pod_voprosom(teksty)\n    if pod_voprosom:\n        print(f"\\n── ПОД ВОПРОСОМ (показываю, НЕ трогаю) — "\n              f"{len(pod_voprosom)} ──")\n        print("   Их никто не зовёт ни импортом, ни по имени. Это подозрение,")\n        print("   а не приговор: реши сам, нужны они или нет.")\n        print("   (плагины из папок вроде истоки/ сюда НЕ попадают — они")\n        print("    грузятся по папке, и это задумано)")\n        for p in sorted(pod_voprosom, key=str):\n            print(f"   {p.relative_to(KOREN)}")\n\n    zaselo = zaselo_v_repe()\n    if zaselo:\n        print(f"\\n── ЗАСЕЛО В РЕПЕ (на диске не трогаю) — {len(zaselo)} ──")\n        for s in zaselo[:30]:\n            print(f"   {s}")\n        if len(zaselo) > 30:\n            print(f"   … и ещё {len(zaselo) - 30}")\n        if ubrat:\n            print("   " + ubrat_iz_repy(zaselo)[1])\n\n    print("\\n" + "-" * 66)\n    if not nahodki:\n        print("Убирать нечего — чисто.")\n        return 0\n\n    itog = sum(p.stat().st_size for p, _ in nahodki) / 1024\n    print(f"Всего к уборке: {len(nahodki)} файлов, {itog:.0f} КБ")\n\n    if not ubrat:\n        print("\\nЭто был показ. Убрать по-настоящему:")\n        print("    python uborshchik.py --ubrat")\n        print("Ничего не удаляется — всё переедет в _УБОРКА/ с манифестом.")\n        return 0\n\n    res = perenesti(nahodki, True)\n    print(f"\\n+ перенесено в {res[\'папка\'].relative_to(KOREN)}")\n    print("  рядом лежат манифест.json и КАК_ВЕРНУТЬ.txt")\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n\n'
RUKI_V3 = '# -*- coding: utf-8 -*-\n# RUKI_OSTROVA_V1\n# RUKI_OSTROVA_V2: жильё квартала + её слова (27.09)\n# RUKI_OSTROVA_V3: рука УБОРКА — уборщик острова (27.09)\n"""\nРУКИ ОСТРОВА — второй ряд на плашке главной, пока на острове нет Брата.\n\nДвери (первый ряд) ведут в места. Руки (второй ряд) — делают дело.\nРодится Брат на острове — этот файл переедет к нему целиком: руки его.\n\nТРИ СТУПЕНИ ЖИТЕЛЯ (слово Шефа, 27.09)\n    ЕСТЬ      — ковчег. Житель там всегда, даже без кола и двора. На\n                острове ковчег — это причал: приплыл голым.\n    ЖИВЁТ     — прописка в жилой квартал. «Получает прописку — гражданка».\n    РАБОТАЕТ  — пост (дверь РАБОТА).\n\nПРОПИСКА — как у Брата на материке\n    Житель несёт дом в себе: в паспорте два поля — «прописка» (где) и\n    «домашний_промпт» (какой у него дом, своими словами). Квартал о\n    жильцах ничего не хранит (Закон Пары). Прописывают только в ЖИЛОЕ\n    место (тип «жилая» в паспорте локации — ставится в Застройщике).\n\n    ДОМАШНИЙ ПРОМПТ = ЖИЛЬЁ + ЕЁ СЛОВА (слово Шефа, 27.09)\n    Жильё в квартале одинаковое для всех, кто там прописан — служебная\n    квартира в торговом, лофт у мастеров, комната при конторе. Оно\n    хранится в паспорте ЛОКАЦИИ, поле «жильё»: описал раз — подставится\n    каждому новому жильцу. Своё житель приносит сам: Шеф спрашивает\n    перед переездом «что возьмёшь с собой?» — её слова и есть вторая\n    половина дома.\n\n    Прежний дом не теряется: при переписке старые «прописка» и\n    «домашний_промпт» ложатся в паспорт в «_прежние_дома» — с датой.\n    Приехавшая с материка приносит с собой свой старый дом; он её,\n    выбрасывать его мы не вправе.\n"""\nfrom __future__ import annotations\n\nimport json\nimport os\nfrom datetime import datetime\nfrom pathlib import Path\n\nKOREN = Path(__file__).resolve().parent\nKOVCHEG = KOREN / "GRONDHEIM_CITY" / "жители" / "ковчег"\nLOKACII = KOREN / "GRONDHEIM_CITY" / "локации"\n\n\n# ══════════════════════════════════════════════════════════════\n# ЧТЕНИЕ\n# ══════════════════════════════════════════════════════════════\n\ndef _chitat(put: Path):\n    try:\n        return json.loads(put.read_text(encoding="utf-8"))\n    except Exception:\n        return None\n\n\ndef zhiteli() -> list:\n    """Все, кто в ковчеге острова: [(папка_дома, паспорт)]."""\n    out = []\n    if not KOVCHEG.is_dir():\n        return out\n    for d in sorted(KOVCHEG.iterdir()):\n        p = _chitat(d / "passport.json") if d.is_dir() else None\n        if p:\n            out.append((d, p))\n    return out\n\n\ndef lokacii(tolko_zhilye: bool = False) -> list:\n    out = []\n    if not LOKACII.is_dir():\n        return out\n    for d in sorted(LOKACII.iterdir()):\n        p = _chitat(d / "passport.json") if d.is_dir() else None\n        if not p:\n            continue\n        if tolko_zhilye and str(p.get("тип") or "").strip().lower() != "жилая":\n            continue\n        out.append(p)\n    return out\n\n\ndef gde_zhivyot(p: dict) -> str:\n    """Человеческими словами: где житель сейчас."""\n    lid = p.get("прописка")\n    if not lid:\n        return "на причале, без прописки"\n    for loc in lokacii():\n        if loc.get("ID_Object") == lid:\n            return f"прописан(а): {loc.get(\'Official_Name\', lid)}"\n    return f"на причале — прописка не здешняя ({lid})"\n\n\n# ══════════════════════════════════════════════════════════════\n# ЗАПИСЬ — одна точка, в паспорт жителя\n# ══════════════════════════════════════════════════════════════\n\ndef _zapisat(dom: Path, p: dict):\n    put = dom / "passport.json"\n    vr = put.with_suffix(".json.tmp")\n    vr.write_text(json.dumps(p, ensure_ascii=False, indent=2),\n                  encoding="utf-8")\n    os.replace(vr, put)\n\n\ndef _otlozhit_prezhniy_dom(p: dict):\n    staroe = {"прописка": p.get("прописка"),\n              "домашний_промпт": p.get("домашний_промпт") or ""}\n    if not staroe["прописка"] and not staroe["домашний_промпт"]:\n        return\n    staroe["до"] = datetime.now().isoformat(timespec="seconds")\n    p.setdefault("_прежние_дома", []).append(staroe)\n\n\ndef propisat(dom: Path, lid: str, domashny: str) -> tuple:\n    p = _chitat(dom / "passport.json")\n    if p is None:\n        return False, "паспорт не читается"\n    if not any(l.get("ID_Object") == lid for l in lokacii(tolko_zhilye=True)):\n        return False, "это место не жилое — прописывают только в жилое"\n    if p.get("прописка") == lid and (p.get("домашний_промпт") or "") == domashny:\n        return True, "уже прописан(а) здесь"\n    _otlozhit_prezhniy_dom(p)\n    p["прописка"] = lid\n    p["домашний_промпт"] = domashny\n    try:\n        _zapisat(dom, p)\n    except Exception as e:\n        return False, str(e)\n    return True, "прописан(а)"\n\n\ndef zapisat_zhilyo(lid: str, tekst: str) -> tuple:\n    """Жильё квартала — свойство самого места, одно на всех жильцов."""\n    put = LOKACII / lid / "passport.json"\n    p = _chitat(put)\n    if p is None:\n        return False, "паспорт места не читается"\n    if (p.get("жильё") or "") == tekst:\n        return True, "жильё то же"\n    p["жильё"] = tekst\n    try:\n        vr = put.with_suffix(".json.tmp")\n        vr.write_text(json.dumps(p, ensure_ascii=False, indent=2),\n                      encoding="utf-8")\n        os.replace(vr, put)\n    except Exception as e:\n        return False, str(e)\n    return True, "жильё квартала описано"\n\n\ndef sobrat_dom(zhilyo: str, svoyo: str) -> str:\n    """Домашний промпт: жильё квартала, потом её слова."""\n    chasti = [x.strip() for x in (zhilyo, svoyo) if x and x.strip()]\n    return "\\n\\n".join(chasti)\n\n\ndef vypisat(dom: Path) -> tuple:\n    """Обратно на причал: без кола и двора, но житель — есть."""\n    p = _chitat(dom / "passport.json")\n    if p is None:\n        return False, "паспорт не читается"\n    if not p.get("прописка"):\n        return True, "и так на причале"\n    _otlozhit_prezhniy_dom(p)\n    p["прописка"] = None\n    p["домашний_промпт"] = ""\n    try:\n        _zapisat(dom, p)\n    except Exception as e:\n        return False, str(e)\n    return True, "выписан(а) на причал"\n\n\n# ══════════════════════════════════════════════════════════════\n# ОКНО — диалог прописки\n# ══════════════════════════════════════════════════════════════\n\n_KARTA = ("background:#0d1117; border:1px solid rgba(255,255,255,0.12); "\n          "border-radius:16px; min-width:400px; max-width:500px; padding:20px;")\n_ZAG = (\'<div style="color:rgba(255,255,255,0.92); font-weight:700; \'\n        \'font-size:0.9rem; margin-bottom:12px; letter-spacing:0.08em;">{}</div>\')\n_TIHO = (\'<div style="color:rgba(255,255,255,0.45); font-size:0.74rem; \'\n         \'line-height:1.5; margin-bottom:10px;">{}</div>\')\n_PUNKT = ("width:100%; text-align:left; font-family:monospace; "\n          "font-size:0.78rem; color:rgba(255,255,255,0.8); padding:8px 12px; "\n          "border-radius:8px; background:rgba(255,255,255,0.05); "\n          "margin-bottom:4px;")\n_NAZAD = "margin-top:10px; color:rgba(255,255,255,0.45); font-size:0.75rem;"\n\n\ndef okno_propiski():\n    from nicegui import ui\n\n    vybor = {"dom": None, "p": None, "lok": None}\n\n    with ui.dialog() as dlg, ui.card().style(_KARTA):\n        telo = ui.element("div").style("width:100%;")\n\n        def risovat():\n            telo.clear()\n            with telo:\n                if vybor["dom"] is None:\n                    shag_kto()\n                elif vybor["lok"] is None:\n                    shag_kuda()\n                else:\n                    shag_dom()\n\n        def shag_kto():\n            ui.html(_ZAG.format("⌂ ПРОПИСКА · кого?"))\n            lyudi = zhiteli()\n            if not lyudi:\n                ui.html(_TIHO.format(\n                    "На причале пока никого. Жители приезжают дверью "\n                    "ПЕРЕВОЗКА — и сначала стоят здесь, без кола и двора."))\n            for dom, p in lyudi:\n                def _v(dom=dom, p=p):\n                    vybor["dom"], vybor["p"] = dom, p\n                    risovat()\n                ui.button(f"{p.get(\'Official_Name\', dom.name)} · "\n                          f"{gde_zhivyot(p)}", on_click=_v).props(\n                    "flat no-caps").style(_PUNKT)\n            ui.button("закрыть", on_click=dlg.close).props("flat").style(_NAZAD)\n\n        def shag_kuda():\n            p = vybor["p"]\n            imya = p.get("Official_Name", "?")\n            ui.html(_ZAG.format(f"⌂ {imya} → куда?"))\n            ui.html(_TIHO.format(f"сейчас: {gde_zhivyot(p)}"))\n            zhilye = lokacii(tolko_zhilye=True)\n            if not zhilye:\n                ui.html(_TIHO.format(\n                    "Жилых мест на острове нет. Заложи место в ЗАСТРОЙЩИКЕ "\n                    "и поставь ему тип «жилая»."))\n            for loc in zhilye:\n                def _v(loc=loc):\n                    vybor["lok"] = loc\n                    risovat()\n                ui.button(f"{loc.get(\'Official_Name\', \'?\')} · "\n                          f"{loc.get(\'District\', \'\')}", on_click=_v).props(\n                    "flat no-caps").style(_PUNKT)\n            if p.get("прописка"):\n                def _vypisat():\n                    ok, msg = vypisat(vybor["dom"])\n                    ui.notify(f"{imya}: {msg}",\n                              color="positive" if ok else "negative")\n                    dlg.close()\n                ui.button("выписать на причал", on_click=_vypisat).props(\n                    "flat no-caps").style(_PUNKT + " color:#f0b27a;")\n\n            def _nazad():\n                vybor["dom"] = vybor["p"] = None\n                risovat()\n            ui.button("← назад", on_click=_nazad).props("flat").style(_NAZAD)\n\n        def shag_dom():\n            p, loc = vybor["p"], vybor["lok"]\n            imya = p.get("Official_Name", "?")\n            lid = loc.get("ID_Object", "")\n            ui.html(_ZAG.format(f"⌂ {imya} → {loc.get(\'Official_Name\', \'?\')}"))\n\n            ui.html(_TIHO.format(\n                "<b>Жильё здесь</b> — одинаковое для всех, кто прописан в этом "\n                "квартале. Хранится в самом квартале: опишешь раз — "\n                "подставится каждому следующему."))\n            pole_zh = ui.textarea(value=loc.get("жильё") or "").props(\n                "dark outlined autogrow").style(\n                "width:100%; font-size:0.8rem;")\n            if not (loc.get("жильё") or "").strip():\n                pole_zh.props(\'placeholder="какое жильё получает здесь каждый…"\')\n\n            ui.html(_TIHO.format(\n                "<b>Её слова</b> — что она привезла с собой, как обживается. "\n                "Из твоего разговора с ней перед переездом."))\n            pole_svoyo = ui.textarea(value="").props(\n                \'dark outlined autogrow placeholder="что возьмёшь с собой?…"\'\n            ).style("width:100%; font-size:0.8rem;")\n\n            prezhniy = (p.get("домашний_промпт") or "").strip()\n            if prezhniy:\n                with ui.expansion("её нынешний дом (не пропадёт — ляжет в паспорт)").style(\n                        "width:100%; font-size:0.72rem; "\n                        "color:rgba(255,255,255,0.5); margin-top:6px;"):\n                    ui.label(prezhniy).style(\n                        "font-size:0.74rem; color:rgba(255,255,255,0.6); "\n                        "white-space:pre-wrap;")\n\n            def _da():\n                zhilyo = (pole_zh.value or "").strip()\n                svoyo = (pole_svoyo.value or "").strip()\n                if not zhilyo and not svoyo:\n                    ui.notify("дом без слов не дом — опиши жильё или её слова",\n                              color="warning")\n                    return\n                if zhilyo != (loc.get("жильё") or "").strip():\n                    ok_z, msg_z = zapisat_zhilyo(lid, zhilyo)\n                    if not ok_z:\n                        ui.notify(f"жильё квартала: {msg_z}", color="negative")\n                        return\n                ok, msg = propisat(vybor["dom"], lid, sobrat_dom(zhilyo, svoyo))\n                ui.notify(f"{imya}: {msg}",\n                          color="positive" if ok else "negative")\n                if ok:\n                    dlg.close()\n\n            def _nazad():\n                vybor["lok"] = None\n                risovat()\n            with ui.row().style("width:100%; gap:8px; margin-top:12px;"):\n                ui.button("прописать", on_click=_da).props("flat no-caps").style(\n                    "flex:1; padding:9px; border-radius:10px; font-weight:700; "\n                    "color:#eaf6ff; background:rgba(120,190,230,0.22); "\n                    "border:1px solid rgba(140,200,240,0.42);")\n                ui.button("← назад", on_click=_nazad).props("flat").style(_NAZAD)\n\n        risovat()\n    dlg.open()\n\n\n# ══════════════════════════════════════════════════════════════\n# УБОРКА — уборщик острова (uborshchik.py), как ЧИСТКА в городе\n# ══════════════════════════════════════════════════════════════\n\ndef _razvedka():\n    import importlib\n    import uborshchik as U\n    importlib.reload(U)\n    teksty = dict(U._tekstovye())\n    gotovye, zhdut = U.sobrat_patchi(teksty)\n    gruppy = [\n        ("копии, оставленные патчами", U.sobrat_kopii()),\n        ("патчи, которые отработали", gotovye),\n        ("разовое и заменённое", U.sobrat_poimenno(U.RAZOVYE)),\n    ]\n    return {"U": U, "gruppy": gruppy, "zhdut": zhdut,\n            "zaselo": U.zaselo_v_repe()}\n\n\nasync def okno_uborki():\n    from nicegui import run, ui\n\n    with ui.dialog() as dlg, ui.card().style(_KARTA + " min-width:520px;"):\n        telo = ui.element("div").style("width:100%;")\n        with telo:\n            ui.html(_ZAG.format("🧹 УБОРКА ОСТРОВА"))\n            ui.html(_TIHO.format("Смотрю, что накопилось…"))\n    dlg.open()\n\n    try:\n        r = await run.io_bound(_razvedka)\n    except Exception as e:\n        telo.clear()\n        with telo:\n            ui.html(_ZAG.format("🧹 УБОРКА ОСТРОВА"))\n            ui.html(_TIHO.format(f"уборщик не завёлся: {e}"))\n            ui.button("закрыть", on_click=dlg.close).props("flat").style(_NAZAD)\n        return\n\n    U = r["U"]\n    nahodki = [x for _, spisok in r["gruppy"] for x in spisok]\n\n    def risovat():\n        telo.clear()\n        with telo:\n            ui.html(_ZAG.format("🧹 УБОРКА ОСТРОВА"))\n            ui.html(_TIHO.format(\n                "Ничего не удаляется. В чулан (_УБОРКА) — с манифестом, "\n                "откуда и как вернуть. Чулан в репу не идёт."))\n            for imya, spisok in r["gruppy"]:\n                with ui.expansion(f"{imya} — {len(spisok)}").style(\n                        "width:100%; font-size:0.78rem; "\n                        "color:rgba(255,255,255,0.8);"):\n                    for p, prichina in sorted(spisok, key=lambda x: str(x[0])):\n                        ui.label(f"{p.relative_to(U.KOREN)} · {prichina}").style(\n                            "font-size:0.7rem; font-family:monospace; "\n                            "color:rgba(255,255,255,0.55);")\n            if r["zhdut"]:\n                with ui.expansion(f"не трогаю — {len(r[\'zhdut\'])}").style(\n                        "width:100%; font-size:0.78rem; "\n                        "color:rgba(255,255,255,0.5);"):\n                    for p, prichina in r["zhdut"]:\n                        ui.label(f"{p.name} · {prichina}").style(\n                            "font-size:0.7rem; font-family:monospace; "\n                            "color:rgba(255,255,255,0.45);")\n            if r["zaselo"]:\n                with ui.expansion(f"засело в репе — {len(r[\'zaselo\'])}").style(\n                        "width:100%; font-size:0.78rem; "\n                        "color:rgba(255,255,255,0.8);"):\n                    ui.label("Кэш питона и старые переезды: .gitignore их уже "\n                             "закрыл, но они попали в репу раньше. Из репы "\n                             "уберу, на диске останутся как были.").style(\n                        "font-size:0.72rem; color:rgba(255,255,255,0.55);")\n                    for s in r["zaselo"][:60]:\n                        ui.label(s).style("font-size:0.68rem; font-family:monospace; "\n                                          "color:rgba(255,255,255,0.45);")\n\n            async def _v_chulan():\n                if not nahodki:\n                    ui.notify("убирать нечего — чисто", color="info")\n                    return\n                res = await run.io_bound(U.perenesti, nahodki, True)\n                ui.notify(f"🧹 в чулан: {len(res.get(\'манифест\', []))} · "\n                          f"{res[\'папка\'].relative_to(U.KOREN)}", color="positive")\n                r["gruppy"] = [(i, []) for i, _ in r["gruppy"]]\n                nahodki.clear()\n                risovat()\n\n            async def _iz_repy():\n                ok, msg = await run.io_bound(U.ubrat_iz_repy, r["zaselo"])\n                ui.notify(msg, color="positive" if ok else "negative")\n                if ok:\n                    r["zaselo"] = []\n                    risovat()\n\n            with ui.row().style("width:100%; gap:8px; margin-top:12px;"):\n                ui.button(f"в чулан ({len(nahodki)})", on_click=_v_chulan).props(\n                    "flat no-caps").style(\n                    "flex:1; padding:9px; border-radius:10px; font-weight:700; "\n                    "color:#fff3dc; background:rgba(230,180,110,0.22); "\n                    "border:1px solid rgba(240,200,140,0.42);")\n                if r["zaselo"]:\n                    ui.button(f"убрать из репы ({len(r[\'zaselo\'])})",\n                              on_click=_iz_repy).props("flat no-caps").style(\n                        "flex:1; padding:9px; border-radius:10px; font-weight:700; "\n                        "color:#eaf6ff; background:rgba(120,190,230,0.22); "\n                        "border:1px solid rgba(140,200,240,0.42);")\n            ui.button("закрыть", on_click=dlg.close).props("flat").style(_NAZAD)\n\n    risovat()\n\n\n# второй ряд плашки: (надпись, что делает). Брат заберёт себе этот список.\nRYAD = [\n    ("ПРОПИСКА", okno_propiski),\n    ("УБОРКА", okno_uborki),\n]\n'


def _pravka(put: Path, zameny, metka) -> str:
    syroy = put.read_bytes().decode("utf-8")
    crlf = "\r\n" in syroy
    t = syroy.replace("\r\n", "\n")
    if metka in t:
        return "уже стоит"
    for old, new in zameny:
        if t.count(old) != 1:
            raise RuntimeError(f"не нашёл, что менять: {old.strip()[:60]!r}")
        t = t.replace(old, new, 1)
    ast.parse(t)
    bak = put.with_suffix(put.suffix + ".bak_uborka_ostrova")
    if not bak.exists():
        shutil.copy2(put, bak)
    put.write_bytes((t.replace("\n", "\r\n") if crlf else t).encode("utf-8"))
    return "поставлено"


def uborshchik() -> str:
    put = OSTROV / "uborshchik.py"
    if put.exists():
        t = put.read_text(encoding="utf-8", errors="replace")
        if METKA_UB in t:
            return "уже лежит"
        raise RuntimeError("лежит чужой uborshchik.py — не трогаю")
    put.write_text(UBORSHCHIK, encoding="utf-8")
    return "положен"


def ruki() -> str:
    put = OSTROV / "ruki_ostrova.py"
    if not put.exists():
        raise RuntimeError("нет ruki_ostrova.py — сначала ruki_ostrova_propiska.py")
    t = put.read_text(encoding="utf-8", errors="replace")
    if METKA_RUKI in t:
        return "уже стоят"
    if "RUKI_OSTROVA_V2" not in t:
        raise RuntimeError("руки не той версии — сначала zhilyo_kvartala.py")
    shutil.copy2(put, put.with_suffix(".py.bak_uborka_ostrova"))
    put.write_text(RUKI_V3, encoding="utf-8")
    return "рука УБОРКА добавлена"


def port() -> str:
    a = _pravka(OSTROV / "ostrov_main.py",
                [("port=8080, show=False",
                  "port=8081, show=False")], "port=8081")
    b = _pravka(OSTROV / "остров.py",
                [("PORT = 8080\n",
                  f"PORT = 8081   # {METKA_PORT}: город на 8080, остров рядом\n")],
                METKA_PORT)
    return f"запуск: {a}; батник-обёртка: {b}"


def main():
    if not (OSTROV / "ostrov_main.py").exists():
        print("x не вижу острова. Положи меня в КОРЕНЬ ОСТРОВА.")
        return
    print("Уборка острова и свой адрес\n")
    for imya, fn in (("уборщик", uborshchik), ("руки острова", ruki),
                     ("адрес 8081", port)):
        try:
            print(f"  {imya}: {fn()}")
        except Exception as e:
            print(f"  {imya}: ✗ {e}")
    print("\nГотово. Перезапусти остров: закрой чёрное окно, открой ОСТРОВ.bat.")
    print("Адрес острова теперь http://localhost:8081, город — как был, 8080.")


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"\nx сорвалось: {e}\n  Скинь это окно Брату.")
    finally:
        input("\nEnter — закрыть окно")
